INSERT INTO dodo_rank_config (store_id, version)
SELECT id, 0 FROM store WHERE id = #{storeId}
ON DUPLICATE KEY UPDATE store_id = VALUES(store_id)

mapper.select:
SELECT ranked.* FROM (
    SELECT r.*, ROW_NUMBER() OVER (PARTITION BY parent_id ORDER BY sort_order, id DESC) AS board_rank
    FROM dodo_theme_top_goods_ref r
    WHERE r.store_id = #{storeId} AND r.status = 1 AND r.parent_id IN
    #{boardId}
) ranked
JOIN dodo_theme_top_list b ON b.id = ranked.parent_id AND b.store_id = #{storeId}
WHERE b.status = 1 AND b.is_prod = 1 AND ranked.board_rank <= 3
ORDER BY ranked.parent_id, ranked.board_rank

mapper.update:
UPDATE dodo_theme_top_list SET sort_order = #{board.sortOrder}, association_priority = #{board.associationPriority},
    recommend_position = #{board.recommendPosition,jdbcType=INTEGER}
WHERE store_id = #{storeId} AND id = #{board.id} AND status = 1
